	const _ = -(unsafe.Sizeof(types.Constant{}) - unsafe.Sizeof(types.TNode[string]{})) // the sizes are equal (tmatchAs)
	x, _ := v.(*pegort.TMatch)
	if x == nil || x.Nt != types.PegoNodeTypes[1] {
		return nil
	}
	return pegort.TMatchAs[types.Constant](x)
